# as mod_attach_top + box.path and the same box::use run on every crew worker via r_arguments '-e'
# Generated by ../../04-targets.R. Run here: Rscript -e 'targets::tar_make()'  (USE_CREW=true for crew)
library(targets)
if (Sys.getenv("USE_CREW") == "true")
  tar_option_set(controller = crew::crew_controller_local(name = "crew", workers = 2, seconds_idle = 10))
tar_option_set(error = "continue")   # every target reports its own outcome

options(box.path = getwd())
box::use(mods/tfuns[add_x])
worker_setup <- sprintf("options(box.path = %s); box::use(mods/tfuns[add_x])", deparse(getwd()))
if (Sys.getenv("USE_CREW") == "true") tar_option_set(controller = crew::crew_controller_local(name = "crew",
  workers = 2, seconds_idle = 10, r_arguments = c("--no-save", "--no-restore", "-e", worker_setup)))

list(
  tar_target(raw, data.frame(var1 = 1:3)),
  tar_target(out, add_x(raw)),
  tar_target(ran_on, Sys.getenv("CREW_CONTROLLER", "main process"))
)
